CREATE OR REPLACE FUNCTION public._q31_staged_test(_sql text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN BEGIN EXECUTE _sql; RAISE EXCEPTION 'Suite must abort to roll back fixtures'; EXCEPTION WHEN OTHERS THEN RETURN SQLERRM; END; END $$; REVOKE ALL ON FUNCTION public._q31_staged_test(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public._q31_staged_test(text) TO service_role; COMMENT ON FUNCTION public._q31_staged_test(text) IS 'Temporary service-role-only rollback verification for Q43-48; retire after verification.';